<script lang="ts">
 import {tick} from 'svelte';
 import type {PublicSetup} from './setup';
 import type {TurnMove} from './turn';
 import {technologySlots,basicActions} from './manifest';
 import {levelTwoBlocker,levelTwoCost} from './discovery';
 import {cardById} from './cards';
 let {game,busy,allowed,send,inspect,compact=false}:{game:PublicSetup;compact?:boolean;busy:boolean;allowed:boolean;send:(move:TurnMove)=>void;inspect:(id:string)=>void}=$props();
 let slot=$state(''),space=$state(0);
 const actor=$derived(game.players.find(p=>p.position===game.activePosition)!);
 const reason=$derived(slot?levelTwoBlocker(game,space,slot):'Choose a Level II space on the Technology board.');
 const known=$derived(game.technologies.find(t=>t.slot===slot));
 const title=$derived(known?cardById(known.card).title:slot);
 async function selectSlot(id:string,event:MouseEvent){
  const control=event.currentTarget as HTMLButtonElement,region=control.parentElement!;slot=id;await tick();
  const target=control.getBoundingClientRect(),window=region.getBoundingClientRect();
  const delta=target.bottom>window.bottom-10?target.bottom-window.bottom+10:target.top<window.top+4?target.top-window.top-4:0;
  if(delta)region.scrollBy({top:delta,behavior:'instant'});
 }

</script>
<section class="level-two-plan" class:compact aria-label="Level II research plan" aria-busy={busy||((game.turn??0)>=game.count&&!game.discovery?.powerReady)}>
 <div class="spaces" role="group" aria-label="Level II action spaces">{#each basicActions.find(a=>a.id==='research-II')!.spaces[game.count] as extra,i}{@const occupied=game.players.find(p=>p.actionLocation===`research-II:${i}`)}<button aria-pressed={space===i} onclick={()=>space=i}><strong>Space {i+1}</strong><span>{2+extra} Ore</span><small>{occupied?`Occupied · ${occupied.name}`:'Open'}</small></button>{/each}</div>
 <p class="instruction">Select a technology with every prerequisite researched. A permanent Population cube and Ore are paid before any Event or candidates are revealed.</p>
 <p class="scroll-cue">Six public Level II positions · scroll to review every prerequisite</p>
 <!-- svelte-ignore a11y_no_noninteractive_tabindex (Named positions support keyboard scrolling in portrait.) -->
 <div class="slots" tabindex="0" role="region" aria-label="Level II positions">{#each technologySlots.filter(s=>s.level==='II') as node}{@const technology=game.technologies.find(t=>t.slot===node.id)}{@const missing=node.prerequisites.filter(id=>!actor.research.includes(game.technologies.find(t=>t.slot===id)!.card))}<button class:chosen={slot===node.id} aria-pressed={slot===node.id} onclick={event=>{void selectSlot(node.id,event);}}><span class="slot-seal" aria-hidden="true">II</span><div><strong>{compact?node.id:technology?cardById(technology.card).title:node.id+' · undiscovered'}</strong>{#if !compact}<small>{node.prerequisites.map(id=>cardById(game.technologies.find(t=>t.slot===id)!.card).title).join(' + ')}</small>{/if}<span>{compact?(missing.length?'Prerequisite missing':technology?'Discovered':'Available'):missing.length?'Prerequisites not yet researched':technology?'Public technology':'Event remains face down'}</span></div></button>{/each}</div>
 <div class="commit-research" aria-live="polite"><div><strong>{title||'Level II research'}</strong>{#if compact&&slot&&!reason}<small>{technologySlots.find(s=>s.id===slot)!.prerequisites.map(id=>cardById(game.technologies.find(t=>t.slot===id)!.card).title).join(' + ')}</small>{/if}<p>{slot?`Pay 1 Population permanently +${levelTwoCost(game.count,space,slot,game.discovery)} Ore.`:'Planning and inspection spend nothing.'}</p>{#if reason}<p class="blocker">{reason}</p>{:else if !known}<p>Revealing this Event cannot be undone.</p>{/if}</div>{#if known}<button onclick={()=>inspect(known.card)}>Inspect full card</button>{/if}<button class="primary" disabled={busy||!allowed||!!reason||!game.discovery?.powerReady} onclick={()=>send({kind:'research-II',space,slot})}>{known?'Research '+title:'Pay & reveal '+(slot||'Event')}</button></div>
</section>
<style>
.level-two-plan{height:100%;min-height:0;display:flex;flex-direction:column;gap:10px;container-type:inline-size}.spaces,.instruction,.scroll-cue,.commit-research{flex:none}.instruction{margin:0}.scroll-cue{font-size:12px;color:#e1d1a9;margin:0}.slots{flex:1;min-height:0;overflow:auto;padding:4px 5px 10px;scrollbar-color:#c5ab70 #112b31;align-content:start}.spaces{display:flex;gap:10px}.spaces button{flex:1;display:grid;gap:3px}.spaces small{font-size:11px}.instruction{font-size:14px;line-height:1.45;color:#d4d6c5}.slots{display:grid;grid-template-columns:1fr 1fr;gap:12px}.slots button{display:flex;align-items:center;gap:13px;text-align:left;min-height:105px;background:radial-gradient(ellipse at 20% 20%,#365353,#122a33);box-shadow:inset 0 0 0 3px #a58d4d25,0 4px #796039}.slot-seal{font:40px 'Cormorant Garamond',serif;display:grid;place-items:center;border:1px solid #aa955f;border-radius:50%;width:54px;height:54px;flex-shrink:0}.slots strong,.slots small,.slots div>span{display:block}.slots strong{font:600 23px 'Cormorant Garamond',serif;color:#f3e8c8}.slots small{margin:5px 0;font-size:12px;color:#d3d6c4}.slots div>span{font-size:11px;color:#b4cdc6}.chosen,button[aria-pressed=true]{outline:2px solid #7ae1ce;outline-offset:-3px}.commit-research{position:static;display:flex;gap:12px;align-items:center;justify-content:space-between;padding:16px;border:1px solid #b3a06c;border-radius:9px;background:#122c33;box-shadow:0 -8px 20px #0c202bb0}.commit-research p{font-size:13px;margin:5px 0}.blocker{color:#f5d4a2}button{min-height:44px;padding:10px 14px;border:1px solid #baa065;border-radius:7px;background:linear-gradient(130deg,#354c48,#152f37);color:#eee5cb;font:14px 'Atkinson Hyperlegible',sans-serif;cursor:pointer}button:focus-visible{outline:3px solid #71eee7;outline-offset:3px}button:disabled{opacity:.55;cursor:default}.primary{background:#15575a;max-width:43%}@container(max-width:620px){.slots{grid-template-columns:1fr}.commit-research{flex-wrap:wrap;padding:12px}.commit-research>div{width:100%}.primary{max-width:none;flex:1}.spaces{gap:6px}.spaces button{padding:8px 4px;font-size:12px}}
@container(max-width:620px){.slot-seal{width:40px;height:40px;font-size:29px}.slots button{min-height:88px;gap:10px}.slots strong{font-size:21px}.instruction{font-size:12px}.commit-research p{font-size:12px}}
@container(min-width:621px){.slots{gap:10px}.spaces button{grid-template-columns:1fr auto;text-align:left;align-items:center;padding:8px 12px}.spaces small{grid-column:1 / -1}.slots button{min-height:80px;padding:8px 10px}.slots strong{font-size:21px}.slots small{margin:3px 0}.slot-seal{width:45px;height:45px;font-size:32px}.instruction{font-size:13px}}
.compact{gap:6px}.compact .instruction{display:none}.compact .spaces{gap:5px}.compact .spaces button{display:flex;align-items:center;justify-content:center;flex-wrap:wrap;gap:2px 4px;padding:4px;font-size:11px;min-height:44px}.compact .spaces small{width:100%;font-size:9px}.compact .slots{flex:none;overflow:visible;grid-template-columns:repeat(3,minmax(0,1fr));gap:6px;padding:3px}.compact .slots button{min-height:44px;padding:5px;display:block;text-align:center}.compact .slot-seal{display:none}.compact .slots strong{font-size:17px}.compact .slots div>span{font-size:10px}.compact .scroll-cue{font-size:10px}.compact .commit-research{flex-wrap:nowrap;padding:9px;gap:8px}.compact .commit-research>div{width:auto;flex:1;min-width:0}.compact .commit-research strong{font-size:13px}.compact .commit-research p,.compact .commit-research small{display:block;font-size:11px;line-height:1.3;margin:4px 0}.compact .primary{max-width:40%;font-size:11px;padding:8px;flex:initial}
</style>
